using Microsoft.AspNetCore.Diagnostics;
using Microsoft.AspNetCore.Mvc;

namespace OrderFlow.Api.Errors;

/// <summary>
/// The single place where exceptions become ProblemDetails, so no layer needs try/catch to shape an HTTP
/// error. Partial because the log methods are generated by [LoggerMessage].
/// </summary>
public sealed partial class GlobalExceptionHandler(IProblemDetailsService problemDetailsService, ILogger<GlobalExceptionHandler> logger) : IExceptionHandler
{
    private readonly IProblemDetailsService _problemDetailsService = problemDetailsService;
    private readonly ILogger<GlobalExceptionHandler> _logger = logger;

    public async ValueTask<bool> TryHandleAsync(HttpContext httpContext, Exception exception, CancellationToken cancellationToken)
    {
        int statusCode;
        string title;
        string type;

        // A request the client walked away from never gets here: the exception handler middleware skips every
        // handler while RequestAborted is signalled, since nobody is left to read a response. A cancellation that
        // does reach this point came from a server-side timeout or a linked token (an HttpClient timeout, for
        // example), so it is a real fault: logged as a warning and answered with 504 instead of 500.
        if (exception is OperationCanceledException)
        {
            statusCode = StatusCodes.Status504GatewayTimeout;
            title = "The request timed out";
            type = ProblemTypes.Timeout;

            LogRequestCancelled(_logger, exception, httpContext.Request.Method, httpContext.Request.Path);
        }
        else
        {
            statusCode = StatusCodes.Status500InternalServerError;
            title = "An unexpected error occurred";
            type = ProblemTypes.Internal;

            LogUnhandledException(_logger, exception, httpContext.Request.Method, httpContext.Request.Path);
        }

        httpContext.Response.StatusCode = statusCode;

        return await _problemDetailsService.TryWriteAsync(new ProblemDetailsContext
        {
            HttpContext = httpContext,
            Exception = exception,
            ProblemDetails = new ProblemDetails
            {
                Status = statusCode,
                Title = title,
                Type = type
            }
        });
    }

    [LoggerMessage(Level = LogLevel.Warning, Message = "{Method} {Path} was cancelled server-side.")]
    private static partial void LogRequestCancelled(ILogger logger, Exception exception, string method, PathString path);

    [LoggerMessage(Level = LogLevel.Error, Message = "Unhandled exception while processing {Method} {Path}.")]
    private static partial void LogUnhandledException(ILogger logger, Exception exception, string method, PathString path);
}